  PRIMARY KEY (`id`),
  KEY `idx_question_asset_question` (`question_id`,`sort_order`),
  KEY `idx_question_asset_content` (`question_content_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='题目图片/附件资源';
